{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.plus_catalog_allocation_hygiene AS WITH actual_inwards AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, MAX(CATEGORY) AS CATEGORY, MIN(INWARD_DATE) AS FIRST_INWARD_DATE, MAX(INWARD_DATE) AS LAST_INWARD_DATE, SUM(QTY) AS TOTAL_INWARDED_QTY FROM snitch_db.maplemonk.plus_inwards_master_2 WHERE INWARD_TYPE = \'ACTUAL_INWARD\' GROUP BY UPPER(TRIM(SKU_GROUP)) ), catalog AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, LIVE_DATE, STATUS, FINAL_STATUS, SHOPIFY_ACTUAL_INV, UNITS_ON_HAND, CREATED_AT_DATE, CATALOGIX_SENT_TIMESTAMP, CATALOGIX_RECEIVED_TIMESTAMP FROM snitch_db.maplemonk.sku_group_sample_to_live QUALIFY ROW_NUMBER() OVER ( PARTITION BY UPPER(TRIM(SKU_GROUP)) ORDER BY LAST_UPDATED_AT_ACTUAL DESC NULLS LAST, LAST_UPDATED_AT DESC NULLS LAST ) = 1 ), store_inventory AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, SUM( CASE WHEN LOWER(TRIM(CUT_SIZE)) = \'cut\' THEN OFFLINE_INVENTORY ELSE 0 END ) AS CUT_SIZE_INVENTORY_QTY, SUM( CASE WHEN LOWER(TRIM(CUT_SIZE)) <> \'cut\' THEN OFFLINE_INVENTORY ELSE 0 END ) AS FULL_SIZE_INVENTORY_QTY, SUM(OFFLINE_INVENTORY) AS STORE_INVENTORY FROM snitch_db.maplemonk.inventory_daily_snapshot_latest WHERE UPPER(TRIM(SKU_GROUP)) LIKE \'4MBG%\' OR UPPER(TRIM(SKU_GROUP)) LIKE \'4B%\' GROUP BY UPPER(TRIM(SKU_GROUP)) ), warehouse_inventory AS ( SELECT UPPER(TRIM(\"Item SkuCode\")) AS SKU_GROUP, SUM(COALESCE(INVENTORY, 0)) AS WAREHOUSE_INVENTORY FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE UPPER(TRIM(\"Item SkuCode\")) LIKE \'4MBG%\' OR UPPER(TRIM(\"Item SkuCode\")) LIKE \'4B%\' GROUP BY UPPER(TRIM(\"Item SkuCode\")) ) SELECT i.SKU_GROUP, i.CATEGORY, i.FIRST_INWARD_DATE, i.LAST_INWARD_DATE, i.TOTAL_INWARDED_QTY, c.CREATED_AT_DATE, c.LIVE_DATE, c.STATUS AS CATALOG_STATUS, c.FINAL_STATUS, c.CATALOGIX_SENT_TIMESTAMP, c.CATALOGIX_RECEIVED_TIMESTAMP, c.SHOPIFY_ACTUAL_INV, c.UNITS_ON_HAND, si.CUT_SIZE_INVENTORY_QTY, si.FULL_SIZE_INVENTORY_QTY, si.STORE_INVENTORY, wi.WAREHOUSE_INVENTORY, CASE WHEN c.SKU_GROUP IS NULL THEN \'INWARDED_NOT_CATALOGUED\' WHEN LOWER(COALESCE(c.STATUS, \'\')) LIKE \'%cancel%\' THEN \'CANCELLED\' WHEN c.LIVE_DATE IS NULL AND LOWER(COALESCE(c.STATUS, \'\')) LIKE \'%draft%\' THEN \'INWARDED_IN_DRAFT\' WHEN wi.WAREHOUSE_INVENTORY > 0 AND si.STORE_INVENTORY IS NULL THEN \'INWARDED_NOT_ALLOCATED\' ELSE \'OK\' END AS HYGIENE_STATUS, CASE WHEN c.SKU_GROUP IS NULL THEN 1 ELSE 0 END AS NOT_CATALOGUED_FLAG, CASE WHEN c.SKU_GROUP IS NOT NULL AND LOWER(COALESCE(c.STATUS, \'\')) LIKE \'%cancel%\' THEN 1 ELSE 0 END AS CANCELLED_FLAG, CASE WHEN c.SKU_GROUP IS NOT NULL AND c.LIVE_DATE IS NULL AND LOWER(COALESCE(c.STATUS, \'\')) LIKE \'%draft%\' THEN 1 ELSE 0 END AS IN_DRAFT_FLAG, CASE WHEN wi.WAREHOUSE_INVENTORY > 0 AND si.STORE_INVENTORY IS NULL THEN 1 ELSE 0 END AS NOT_ALLOCATED_FLAG FROM actual_inwards i LEFT JOIN catalog c ON i.SKU_GROUP = c.SKU_GROUP LEFT JOIN store_inventory si ON i.SKU_GROUP = si.SKU_GROUP LEFT JOIN warehouse_inventory wi ON i.SKU_GROUP = wi.SKU_GROUP;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            